// GENERATED by scripts/build_software_dashboard.py — do not edit by hand.
// Interactive "Supported software" dashboard (matrix / smoke / catalog).
(function () {
  "use strict";
  // Resolve software.json relative to THIS script's URL so it works under the
  // GitHub-Pages project subpath (/trinity_hub/...), not the site root.
  var SCRIPT_SRC = (document.currentScript && document.currentScript.src) || "";
  var DATA_URL = SCRIPT_SRC ? new URL("../software/software.json", SCRIPT_SRC).href : "software.json";

  var CACHE = null;

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function el(id) { return document.getElementById(id); }

  function stateLabel(st) {
    return { pass: "✓", partial: "~", fail: "✗", available: "●",
             in_progress: "…", blocked: "!", listed: "·" }[st] || "";
  }

  function currentFilters() {
    return {
      q: (el("sw-search").value || "").trim().toLowerCase(),
      system: el("sw-system").value || "",
      category: el("sw-category").value || "",
      state: el("sw-state").value || "",
    };
  }

  function appMatches(app, f) {
    if (f.q) {
      var hay = (app.name + " " + app.category + " " + app.description).toLowerCase();
      if (hay.indexOf(f.q) === -1) return false;
    }
    if (f.category && app.category !== f.category) return false;
    if (f.system && !app.systems[f.system]) return false;
    if (f.state) {
      var hit = Object.keys(app.systems).some(function (sid) {
        if (f.system && sid !== f.system) return false;
        return app.systems[sid].state === f.state;
      });
      if (!hit) return false;
    }
    return true;
  }

  function sortRows(rows, key, dir) {
    rows.sort(function (a, b) {
      var x = a[key] == null ? "" : a[key], y = b[key] == null ? "" : b[key];
      if (x < y) return -1 * dir;
      if (x > y) return 1 * dir;
      return 0;
    });
    return rows;
  }

  function renderMatrix(data, f) {
    var systems = data.systems.filter(function (s) { return !f.system || s.id === f.system; });
    var apps = data.apps.filter(function (a) { return appMatches(a, f); });
    var h = ['<p class="sw-count">' + apps.length + " applications × " + systems.length + " systems</p>"];
    h.push('<table class="sw-table sw-matrix"><thead><tr><th>Application</th>');
    systems.forEach(function (s) { h.push("<th title=\"" + esc(s.facility) + '">' + esc(s.name) + "</th>"); });
    h.push("</tr></thead><tbody>");
    apps.forEach(function (a) {
      h.push("<tr><td><strong>" + esc(a.name) + "</strong>");
      if (a.category) h.push('<span class="sw-app-cat">' + esc(a.category) + "</span>");
      h.push("</td>");
      systems.forEach(function (s) {
        var c = a.systems[s.id];
        if (!c) { h.push('<td class="sw-cell"></td>'); return; }
        var tip = c.build ? "build: " + c.build : c.state;
        if (c.smoke_date) tip += " · smoke " + c.state + " " + c.smoke_date;
        if (c.smoke_result) tip += " — " + c.smoke_result;
        h.push('<td class="sw-cell sw-' + c.state + '" title="' + esc(tip) + '">' + stateLabel(c.state) + "</td>");
      });
      h.push("</tr>");
    });
    h.push("</tbody></table>");
    return apps.length ? h.join("") : "";
  }

  function renderSmoke(data, f) {
    var rows = data.smokes.filter(function (r) {
      if (f.system && r.system !== f.system) return false;
      if (f.state && r.state !== f.state) return false;
      if (f.q && (r.app + " " + r.result).toLowerCase().indexOf(f.q) === -1) return false;
      return true;
    });
    var h = ['<p class="sw-count">' + rows.length + " smoke tests</p>"];
    h.push('<table class="sw-table"><thead><tr>' +
      '<th data-sort="app">Application</th><th data-sort="system">System</th>' +
      '<th data-sort="date">Date</th><th data-sort="state">Status</th>' +
      "<th>Result</th></tr></thead><tbody>");
    rows.forEach(function (r) {
      h.push("<tr><td><strong>" + esc(r.app) + "</strong></td><td>" + esc(r.system) +
        "</td><td>" + esc(r.date) + '</td><td><span class="sw-tag sw-' + r.state + '">' +
        esc(r.state) + "</span></td><td>" + esc(r.result) + "</td></tr>");
    });
    h.push("</tbody></table>");
    return rows.length ? h.join("") : "";
  }

  function renderCatalog(data, f) {
    var apps = data.apps.filter(function (a) { return appMatches(a, f); });
    var h = ['<p class="sw-count">' + apps.length + " applications</p>"];
    h.push('<table class="sw-table"><thead><tr>' +
      '<th data-sort="name">Application</th><th data-sort="category">Category</th>' +
      "<th>Description</th><th>Available on</th></tr></thead><tbody>");
    apps.forEach(function (a) {
      var where = Object.keys(a.systems).sort().join(", ");
      h.push("<tr><td><strong>" + esc(a.name) + "</strong></td><td>" +
        (a.category ? '<span class="sw-tag">' + esc(a.category) + "</span>" : "") +
        "</td><td>" + esc(a.description) + "</td><td>" + esc(where) + "</td></tr>");
    });
    h.push("</tbody></table>");
    return apps.length ? h.join("") : "";
  }

  var VIEW = "matrix";

  function draw() {
    if (!CACHE) return;
    var f = currentFilters();
    var html = VIEW === "smoke" ? renderSmoke(CACHE, f)
             : VIEW === "catalog" ? renderCatalog(CACHE, f)
             : renderMatrix(CACHE, f);
    ["matrix", "smoke", "catalog"].forEach(function (v) {
      var node = el("sw-view-" + v);
      if (node) node.hidden = v !== VIEW;
    });
    var target = el("sw-view-" + VIEW);
    target.innerHTML = html;
    el("sw-empty").hidden = !!html;
    // Wire column sorting for the plain tables (not the matrix).
    Array.prototype.forEach.call(target.querySelectorAll("th[data-sort]"), function (th) {
      th.addEventListener("click", function () {
        var key = th.getAttribute("data-sort");
        th._dir = th._dir === 1 ? -1 : 1;
        var arr = VIEW === "smoke" ? CACHE.smokes : CACHE.apps;
        sortRows(arr, key, th._dir);
        draw();
      });
    });
  }

  function populateSelects(data) {
    var sysSel = el("sw-system"), catSel = el("sw-category");
    if (sysSel.options.length <= 1) {
      data.systems.slice().sort(function (a, b) { return a.name < b.name ? -1 : 1; })
        .forEach(function (s) {
          var o = document.createElement("option");
          o.value = s.id; o.textContent = s.name; sysSel.appendChild(o);
        });
    }
    if (catSel.options.length <= 1) {
      var cats = {};
      data.apps.forEach(function (a) { if (a.category) cats[a.category] = 1; });
      Object.keys(cats).sort().forEach(function (c) {
        var o = document.createElement("option");
        o.value = c; o.textContent = c; catSel.appendChild(o);
      });
    }
  }

  function wire() {
    ["sw-search", "sw-system", "sw-category", "sw-state"].forEach(function (id) {
      var node = el(id);
      if (node && !node._wired) {
        node._wired = true;
        node.addEventListener("input", draw);
        node.addEventListener("change", draw);
      }
    });
    Array.prototype.forEach.call(document.querySelectorAll(".sw-tab"), function (tab) {
      if (tab._wired) return;
      tab._wired = true;
      tab.addEventListener("click", function () {
        VIEW = tab.getAttribute("data-view");
        Array.prototype.forEach.call(document.querySelectorAll(".sw-tab"), function (t) {
          t.setAttribute("aria-selected", t === tab ? "true" : "false");
        });
        draw();
      });
    });
  }

  function init() {
    var host = el("sw-dashboard");
    if (!host) return;  // not on the dashboard page
    VIEW = "matrix";
    wire();
    if (CACHE) { populateSelects(CACHE); draw(); return; }
    fetch(DATA_URL).then(function (r) { return r.json(); }).then(function (data) {
      CACHE = data;
      populateSelects(data);
      draw();
    }).catch(function (e) {
      host.innerHTML = '<p class="sw-empty">Could not load software.json: ' + esc(e) + "</p>";
    });
  }

  // Material's instant navigation replaces page content without a full reload;
  // document$ fires on initial load AND after every in-site navigation.
  if (window.document$ && typeof window.document$.subscribe === "function") {
    window.document$.subscribe(init);
  } else if (document.readyState !== "loading") {
    init();
  } else {
    document.addEventListener("DOMContentLoaded", init);
  }
})();
